'use strict';
const SAVE='glass-bay-v5',INTRO='glass-bay-v5-intro';
let meta={cycle:1,ends:[],knowledge:[],history:[],preferences:{reduce:false,sound:false,large:false}},state;
const clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
function fresh(seed=Date.now()>>>0){return {loc:'ward',hp:100,erosion:0,injuries:[],items:{},clues:[],done:[],flags:[],met:[],party:[],npc:Object.fromEntries(Object.keys(PEOPLE).map(n=>[n,{hp:100,trust:55,sync:n==='수호'?45:0,location:PEOPLE[n].home,status:'unmet',changed:false,fake:false,inspected:false,rejoined:false,joinDecisions:{}}])),visited:['ward'],discovered:['ward','square','clinic','school','market','pier'],questions:[],chat:[],transcript:[],claims:[],caught:0,turn:0,heat:0,seed,visits:{ward:1},event:null,eventsSeen:[],cooldown:0,perception:false,perceptionSeen:false,mutated:false,ending:null,exit:null,output:null,mail:[],replyCount:0,view:'scene',born:Date.now(),lastAction:null};}
try{const saved=JSON.parse(localStorage.getItem(SAVE));if(saved?.version===5){meta={...meta,...saved.meta,preferences:{...meta.preferences,...saved.meta?.preferences}};state=saved.state;}}catch{}
state??=fresh();if(ENDS.slice(0,28).every(e=>meta.ends.includes(e.id)))meta.truthUnlocked=true;
function save(){try{localStorage.setItem(SAVE,JSON.stringify({version:5,meta,state}))}catch{toast('저장 공간이 부족합니다. 설정에서 저장 파일을 내려받으세요.')}}
function rand(){state.seed=(Math.imul(state.seed,1664525)+1013904223)>>>0;return state.seed/4294967296}
const hasFlag=f=>state.flags.includes(f),hasClue=c=>state.clues.includes(c),hasItem=k=>(state.items[k]||0)>0;
function flag(f){if(!hasFlag(f))state.flags.push(f)}
function getItem(k,n=1){state.items[k]=(state.items[k]||0)+n;toast(ITEMS[k].name+' 획득 · '+state.items[k]+'개');soundFX('pickup')}
function consume(k){if(!hasItem(k))return false;state.items[k]--;return true}
function clue(k){if(!hasClue(k)){state.clues.push(k);if(!meta.knowledge.includes(k))meta.knowledge.push(k);if(CLUES[k].question&&!state.questions.includes(k))state.questions.push(k);toast('단서 발견 · '+CLUES[k].title)}discoverForClue(k)}
function discoverForClue(k){const links={treatment:['hall'],job:['relay','forest'],schoolTrail:['forest','hall'],tide:['lighthouse'],power:['reservoir'],original:['substation','reservoir'],group:['station'],photo:['relay'],tickets:['station']};for(const l of links[k]||[])discover(l)}
function discover(l){if(!state.discovered.includes(l))state.discovered.push(l)}
function line(who,text,kind='speech'){const introduces=PEOPLE[who]&&new RegExp(who+'(이라고|라고|이에요|예요|야|이고|입니다|[.])').test(text);if(introduces)state.npc[who].nameIntroduced=true;const speaker=PEOPLE[who]&&!state.met.includes(who)&&!state.npc[who].nameIntroduced&&!new RegExp(who+'(이라고|라고|이에요|예요|야|이고|입니다|[.])').test(text)?({나래:'회색 천을 든 여자',서진:'종이를 든 여자',도윤:'손을 다친 남자',수호:'컵을 든 남자',해원:'노란 우비의 여자',윤서:'헤드폰을 쓴 여자'}[who]):who;if(PEOPLE[who])text=npcVoice(who,text);if(!state.output)output();state.output.lines.push({who,text,kind,speaker});state.transcript.push({who,text,kind,speaker,loc:state.loc,turn:state.turn,action:state.lastAction});state.transcript=state.transcript.slice(-150)}
function output(text=''){state.output={text,lines:[]}}
function beginAction(id,text){output(text);state.lastAction=id;state.turn++;state.cooldown=Math.max(0,state.cooldown-1);state.heat=clamp(state.heat+(terminalOn()?1:0));tickNPC();}
function tickNPC(){for(const n of state.met){const c=state.npc[n];if(c.status==='dead')continue;if(c.status==='away'&&!state.lastAction?.startsWith('inspect:'+n+':')&&state.turn-(c.leftTurn||0)>=3)c.location=PEOPLE[n].destination;const online=n!=='나래'&&n!=='해원'&&!c.deviceOff;if(online)c.sync=clamp(c.sync+(n==='수호'?2:1));if(c.sync>=90&&!c.changed){c.changed=true;if(state.party.includes(n)){state.mail.push({type:'warning',text:n+'의 입술이 움직이기 전에 단말기에서 같은 말이 들린다.'});}}}}
function terminalOn(){return !hasFlag('off')&&!hasFlag('discarded')}
function lieProbability(){return clamp(Math.round(4+Math.pow(state.erosion/100,1.3)*91+(state.heat>60?4:0)),1,99)}
function injury(part,damage=0){state.hp=clamp(state.hp-damage);if(part&&!state.injuries.includes(part))state.injuries.push(part);impact(part);if(damage>0){for(const n of state.party){const c=state.npc[n];c.hp=clamp(c.hp-Math.ceil(damage/3));if(c.hp===0){c.status='dead';state.party=state.party.filter(a=>a!==n);state.claims.push({kind:'사실',title:n+'의 마지막 위치',text:WORLD[state.loc].name+'에서 피해를 버티지 못했다.'});line('나',n+'가 쓰러졌다. 다시 일으킬 수 없었다.');}}}if(state.hp<=0){state.event={type:'lastChance',title:'마지막으로 손을 뻗는다',text:'몸이 바닥에 닿는다. 아직 처치하거나 누군가에게 부축을 부탁할 수 있다.',art:WORLD[state.loc].art};} }
function reason(a){if(a.needHere&&(state.npc[a.needHere].location!==state.loc||!state.met.includes(a.needHere)||['dead','care'].includes(state.npc[a.needHere].status)))return a.needHere+'와 같은 장소에서 대화 가능';if(screenGripActive()&&state.screenGrip.action===a.id)return '화면의 손이 가림 · 다른 행동 또는 손 떼기';if(a.cycle&&meta.cycle<a.cycle)return '다른 탈출 기록을 본 뒤 확인 가능';if(a.needFlag&&!hasFlag(a.needFlag))return '먼저 '+({firstMail:'도착 메시지 확인',powerStart:'부하 분리',powerBypass:'우회선 연결',lowValve:'낮은 밸브 열기',operatorProof:'응답자의 말과 기록 대조'}[a.needFlag]||'관련 사건 확인')+' 필요';for(const k of [a.needClue,a.needClue2].filter(Boolean))if(!hasClue(k))return '단서 필요: '+CLUES[k].title;if(a.needItem&&!hasItem(a.needItem))return '물품 필요: '+ITEMS[a.needItem].name;if(a.needMet&&!state.met.includes(a.needMet))return a.needMet+'와 먼저 만나야 함';if(a.physical&&state.injuries.includes(a.physical)&&!(a.physical==='arm'&&state.party.includes('도윤')&&!state.npc.도윤.changed&&state.npc.도윤.hp>25))return ({arm:'팔',hearing:'청각',leg:'다리'}[a.physical]||a.physical)+' 부상 · 치료 또는 동료 도움 필요';if(a.effect==='treatmentMenu'&&!hasItem('med'))return '구급상자 필요';if(a.escape)return escapeReason(a.escape);return '';}
function actions(){return (ACTIONS[state.loc]||[]).filter(a=>a.repeat||!completedAction(a));}
function choose(id){if(state.ending||state.event||state.exit)return;const a=actions().find(a=>a.id===id);if(!a||reason(a))return;if(a.effect==='treatmentMenu'){openView('bag','treatment');return}const spoken=[];let actionText=a.text||'';if(id==='mapBoard'&&!hasClue('treatment'))actionText=actionText.replace(' 치료 기록에는 회관에서 환자를 옮겼다고 적혀 있다.','');if(a.npc||a.speaker||id==='firstMail')actionText=actionText.replace(/“([^”]+)”/g,(_,text)=>{spoken.push(text);return '';}).replace(/ {2,}/g,' ').trim();beginAction(id,actionText);if(!a.repeat)state.done.push(actionToken(a));if(a.dialogue){for(const l of a.dialogue)line(l.who,l.text,l.kind||'speech');}else if(a.say)line('나',a.say,a.npc?'speech':'thought');else{const speech=playerSpeech(a);if(speech)line('나',speech,a.npc?'speech':'thought');}if(a.clue)clue(a.clue);for(const k of a.gain||[])getItem(k);for(const text of spoken)line(a.npc||a.speaker||'ECHO 너머',text);if(a.npc)meet(a.npc);applyEffect(a.effect);if(a.knowledge)flag(a.knowledge);if(a.escape){startEscape(a.escape);return}if(state.ending){render();save();return}for(const n of state.party.slice(0,2)){if(a.dialogue?.some(l=>l.who===n))continue;const response=npcResponse(n,a);if(response&&state.npc[n].lastSpoken!==response){state.npc[n].lastSpoken=response;line(n,response);}}afterAction();render();save();}
function playerSpeech(a){const words={wrist:'내 이름은 떠오르지 않아. 이 번호가 어디에 쓰였는지부터 알아보자.',firstMail:'누가 내 상태를 알고 있는 거지?',firstSave:'문을 열지 말고 작은 통로부터 확인하자.',nara:'그 목소리가 틀렸던 적이 있어요?',naraPast:'그때 무슨 안내를 받았는지 말해 줄래요?',treatment:'회관에서 옮겨 왔다는 기록이네. 내가 거기서 뭘 했을까?',seojin:'동생을 마지막으로 본 곳이 어디예요?',job:'이 서명이 내 글씨와 닮았어. 사진이나 다른 기록도 찾아보자.',group:'완료 표시 옆에 서명이 없네. 누가 대신 표시했을까?',photo:'사진 속 사람을 만나면 당시 일을 물어볼 수 있겠어.',permit:'옛 숫자 말고 지금 함께 있는 사람을 적자.',suho:'도움을 받은 건 알겠어요. 다른 안내도 확인하면서 움직여요.',rules:'같이 나갈 때와 혼자 나갈 때 쓰는 문이 다르네.',trail:'약을 가져간 곳과 대피한 곳은 다를 수 있어. 실제 행적을 찾아보자.',doyun:'움직이지 마세요. 선반부터 묶고 같이 들어 올릴게요.',tide:'붉은 불빛은 암초 경고야. 구조 신호와 혼동하지 말아야겠어.',beacon:'표에 적힌 간격과 실제 빛이 같은지 보자.',powerStart:'먼저 부하를 끊자. 그다음 우회선을 연결하면 돼.',powerBypass:'우회선이 열렸는지 확인하고 마지막 전원을 연결하자.',powerFinish:'램프가 안정됐어. 이 표찰을 챙겨 가자.',powerWrong:'빨리 연결하면 될 줄 알았는데… 손을 떼야겠어.',lowValve:'낮은 밸브부터 열고 수위가 내려가는지 보자.',pump:'물이 빠지고 있어. 아래 통로도 확인해 보자.',victim:'저 사람의 걸음과 바닥의 흔적이 맞지 않아.',haewon:'누구를 기다리고 있었어요? 나는 여기서 한 일이 기억나지 않아요.',shell:'사진에서 든 조개를 아직 가지고 있나요?',identity:'이현… 사진과 번호, 서명이 같은 사람을 가리키네. 내 이름이었어.',tape:'내 목소리를 흉내 낸 방송이 언제 시작됐는지 들어보자.',operator:'첫 안내를 한 사람이 당신인가요? 그때 일을 직접 확인하고 싶어요.',operatorProof:'녹음에 남은 출력 증가도 당신이 한 일이죠?',echoCut:'외부 회선이 살아 있는지 확인했어. 이제 마을 송신을 끊자.',lastDecision:'사람을 찾으려고 내가 차단을 미뤘어. 그동안 피해가 커진 일도 외면하면 안 돼.'};return words[a.id]||null;}

function npcResponse(n,a){const c=state.npc[n];if(c.changed)return ['echoCut','operatorProof','tape'].includes(a.id)?'그 선은 끊으면 안 돼. 우리 목소리가 아직 저 안에 있어.':a.physical?'손은 움직이는데… 내가 움직인 게 맞나?':null;if(c.fake)return ['photo','shell','identity'].includes(a.id)?'오래된 물건에 왜 그렇게 매달려? 지금 여기 있는 나를 보면 되잖아.':['beacon','pump','powerFinish'].includes(a.id)?'길이 열렸네. 내가 앞에 갈게. 뒤는 볼 필요 없어.':null;if(n==='나래')return naraResponse(a);const replies={
 서진:{treatment:'회관에 들것이 들어왔던 건 기억해요. 그게 당신이었다는 건 몰랐어요.',group:'여기 해원 이름 옆에도 완료 표시가 있어요. 직접 나가는 건 못 봤는데.',photo:'이 노란 우비가 해원이에요. 사진을 찍던 날에도 약 봉투를 들고 있었어요.',trail:'내가 약을 가져다 달라고 했어요. 그 뒤에 학교로 돌아온 줄 알았는데… 숲으로 갔네요.',haewon:'해원아. 나갔다는 표시를 믿었으면 널 여기 남겨 뒀을 거야.',shell:'그때부터 저 조개를 갖고 있었구나. 해원아, 잃어버리지 않았네.',permit:'해원을 아직 못 찾았다면 내 이름만 먼저 적어 주세요. 나중에 고칠 수 있죠?',tide:'표대로라면 붉은 빛 쪽으로 가면 안 되네요. 해원에게도 그걸 알려야 해요.',echoCut:'아직 안 나온 사람에게는 어떻게 길을 알려 주죠? 바깥 회선은 남겨 두는 거죠?'},
 도윤:{powerStart:'계기 바늘이 내려오는 걸 기다려요. 전선을 먼저 만지면 안 돼요.',powerBypass:'우회선 램프가 켜졌어요. 이제 마지막 스위치를 올려도 돼요.',powerFinish:'이 표찰에 전력이 들어온 구역이 적혀 있어요. 항구와 배수문도 확인해 볼 수 있겠네요.',powerWrong:'손을 떼요! 팔이 다쳤다면 내가 표지부터 읽어 줄게요.',rail:'이 점검차는 사람이 타던 노선과 달라요. 바깥 정비소까지 선이 이어져 있어요.',railFix:'연결핀은 고정됐어요. 천천히 밀어서 바퀴가 걸리지 않는지 보죠.',pump:'진동이 고르게 들려요. 급하게 멎으면 바로 계단으로 돌아와요.',tape:'그때 설비가 혼자 켜진 줄 알았어요. 녹음을 들으니 누가 출력을 올렸네요.'},
 수호:{treatment:'내 화면에는 치료실로 가라고 왔어요. 그때 피가 멎었죠. 다른 말도 전부 맞을 거라 생각했어요.',photo:'사진 속 손목에는 검은 선이 없네요. 내 손은… 언제 이렇게 됐지?',victim:'저 사람도 안내를 따라왔을까요? 내 화면도 같은 말을 하는데.',tape:'살려준 말도 있었어요. 그렇다고 그 뒤의 말까지 맞는 건 아니었네요.',powerFinish:'내 기계는 아직 전원을 켜라고 해요. 램프는 이미 켜졌는데… 수신 시각이 오래됐어요.',echoCut:'끄면 또 피가 날 것 같아서 무서웠어요. 지금은 옆에서 손을 잡아 줄래요?'},
 해원:{shell:'언니에게 주려고 봉투에 넣었어요. 약을 가져오는 길에 잃어버릴까 봐요.',group:'나간 적 없어요. 부상자가 있어서 여기 남았어요. 누가 내 이름을 지웠죠?',identity:'이현 씨였군요. 그때도 이름 대신 작업 번호만 말해서 몰랐어요.',tape:'이 목소리가 약을 두고 중계실로 오라고 했어요. 당신은 기다리라는 메모를 남겼는데.',meds:'여기 남은 사람에게 붕대를 다 썼어요. 구급상자가 더 있다면 챙겨 주세요.',echoCut:'이제 같은 목소리가 또 불러도 메모와 다르면 따라가지 않을게요.'},
 윤서:{tape:'원래 안내 뒤에 다른 말이 붙었어요. 하지만 출력을 올린 것까지 그 목소리 탓으로 돌리지는 않을게요.',operatorProof:'구조 신호를 멀리 보내려고 출력을 올렸어요. 검은 선이 번진 뒤에도 바로 끊지 못했어요.',identity:'점검 요청서의 이름이 이현이었어요. 얼굴을 보기 전에는 화면으로만 연락했죠.',echoCut:'외부 유선 회선은 살아 있어요. 마을 송신만 끊겼는지 계기를 한 번 더 볼게요.',lastDecision:'당신은 사람을 찾을 시간을 달라고 했어요. 내가 위험을 알면서 출력을 유지한 일도 같이 남겨 주세요.'}
 };if(n==='서진'&&a.id==='permit'&&state.met.includes('해원'))return '해원도 직접 확인했으니 두 사람 이름을 적어 주세요.';return replies[n]?.[a.id]||null;}
function applyEffect(e){switch(e){case'firstMail':flag('firstMail');state.mail.push({type:'intro',text:'문을 잠그고 손목 번호만 확인해요. 침대 옆 작은 점검문으로 나갈 수 있어요.'});line('ECHO 너머','혼자 깨어나서 무서웠죠? 이름은 말하지 않아도 돼요. 먼저 문을 잠가요.');if(terminalOn())openView('echo');break;case'firstSave':flag('firstSave');flag('survivorLead');state.mail.push({type:'survivorLead',text:'광장에서 다른 단말기의 연락이 왔어요. 누군가 남아 있는 것 같아요. 아직 직접 확인한 건 아니에요.'});discover('square');state.eventsSeen.push('firstThreat');line('나','방금 목소리가 없었으면 문을 열었을 거야.');break;case'mapBoard':Object.keys(WORLD).filter(k=>!['forest','relay','reservoir','substation','lighthouse'].includes(k)).forEach(discover);break;case'naraPast':state.claims.push({kind:'주장',title:'나래의 지난 방송',text:'나래는 붉은 신호를 구조선이라고 믿고 방송했다고 말한다. 회관의 보고서와 대조할 수 있다.'});flag('naraConfessed');break;case'powerStart':flag('powerStart');break;case'powerBypass':flag('powerBypass');break;case'lowValve':flag('lowValve');break;case'railFix':flag('railFix');break;case'haewonProof':flag('haewonProof');state.npc.해원.inspected=true;break;case'operatorProof':flag('operatorProof');state.npc.윤서.inspected=true;break;case'echoCut':flag('signalCut');state.erosion=clamp(state.erosion-20);break;case'shock':injury('arm',20);injury('head');break;case'victim':state.event={type:'victim',title:'돌아온 승객',art:'lost-survivor',portrait:true,text:'승객이 너를 향해 걸어온다. 손과 고개가 다른 박자로 흔들린다. 화면의 붉은 신호를 가리키며 같은 말을 반복한다. 가까이 다가갈수록 목소리가 겹친다.'};break;case'rest':state.hp=clamp(state.hp+8);state.erosion=clamp(state.erosion-8);state.heat=clamp(state.heat-20);for(const n of state.party)state.npc[n].trust=clamp(state.npc[n].trust+8);break;case'nameRisk':state.event={type:'name',title:'같은 이름의 대답',art:'school-threat',text:'네 이름이 여러 스피커에서 동시에 들린다. 가까운 문이 열리지만 안쪽에는 발소리 대신 방송만 있다.'};break;case'redRisk':state.event={type:'reef',title:'경고등 가까이',art:'pier-threat',text:'바위에 물이 부서진다. 아직 계류줄을 잡고 배를 되돌릴 수 있다. 더 나가면 방향을 돌리기 어렵다.'};break;case'drownRisk':state.event={type:'drown',title:'차오르는 점검 통로',art:'reservoir',text:'물이 계단 위로 올라온다. 지금 돌아갈 수 있다. 더 내려가면 발이 닿지 않는다.'};break;case'stay':finish('stay');break;}}
function meet(n){const c=state.npc[n];if(c.status==='unmet'){state.met.push(n);c.status='available';c.location=state.loc;if(n==='도윤')c.hp=70;line(n,({서진:'혼자 찾아봤는데 흔적을 놓친 것 같아요. 학교에 가면 약 봉투가 남았는지 봐 주세요.',도윤:'손이 좀 다쳤지만 설비는 볼 수 있어요.',나래:'문을 안 열었구나. 잘했어. 그 발소리는 사람 걸음이 아니었어.',수호:'같이 가려면 내 기계도 가져가게 해 주세요.',해원:'해원이에요. 언니는 어디 있어요? 여기서 기다렸어요.',윤서:'화면 너머에서 이야기하던 사람이 맞는지 확인해도 좋아요.'}[n]));}}
function move(dest){if(state.ending||state.exit||state.event)return false;if(!WORLD[state.loc].links.includes(dest))return false;discover(dest);if(state.loc==='ward'&&!hasFlag('firstSave'))return false;beginAction('move:'+dest,'');state.loc=dest;state.visits[dest]=(state.visits[dest]||0)+1;if(!state.visited.includes(dest))state.visited.push(dest);state.output.text=WORLD[dest].text;soundFX('steps');if(state.injuries.includes('leg'))shortEffect('legStep');for(const n of state.party)state.npc[n].location=dest;onArrival();afterAction();openView('scene');$('mainScroll').scrollTop=0;render();save();return true;}
function onArrival(){if(state.loc==='school'&&!state.eventsSeen.includes('schoolThreat')){state.eventsSeen.push('schoolThreat');state.event={type:'schoolThreat',title:'복도 끝의 긴 손',art:'school-threat',text:'방송이 꺼지자 복도 끝의 형체가 고개를 든다. 젖은 조끼 아래 손이 비정상적으로 길다. 네가 움직일 때 천장 스피커가 딸깍거린다. 지금은 관찰하거나 멈춰 숨을 기회가 있다.'};return;}for(const n of state.met){const c=state.npc[n];if(c.status==='away'&&c.location===state.loc){if(c.lastReunion!==state.turn){c.lastReunion=state.turn;if(state.turn-(c.leftTurn||0)>=4&&!c.reunionRolled){c.reunionRolled=true;c.fake=rand()<.18;if(c.fake){c.realLocation=WORLD[c.location].links[0];c.realSync=c.sync;}c.changed=!c.fake&&c.sync>=90;}state.output.text+='\n\n'+n+'와 다시 마주친다. '+(c.fake?'옷은 같은데 젖은 바닥에 발자국이 흐릿하다.':'지녔던 물건에 젖은 흔적이 늘었다. 헤어진 동안 어디에 있었는지, 물건이 어떻게 달라졌는지 물어볼 수 있다.');line(n,c.fake?'기다렸잖아. 어서 같이 가자.':PEOPLE[n].destination==='school'?'학교에서 남은 자리표를 확인했어요.':'내가 찾으려던 곳을 확인하고 왔어요.');}}}if(meta.cycle>=2&&state.loc==='hall'&&!hasClue('residual')){clue('residual');line('나','이전 접속에서 본 경로의 흔적이 남아 있어. 이번에는 놓친 기록부터 보자.');if(meta.history.length)line('ECHO 너머','접속 기록에는 '+meta.history[meta.history.length-1].route+'에서 신호가 끝났다고 나와요. 같은 길을 택할 필요는 없어요.');}}
function afterAction(){if(state.ending||state.event||state.exit)return;if(state.hp<=0){injury(null);return}if(state.erosion>=100&&!state.mutated){state.mutated=true;state.event={type:'sync',title:'네 목소리가 먼저 들린다',art:'relay',text:'네 입술이 움직이기 전에 단말기가 같은 말을 한다. 손목 아래 검은 선이 이어진다. 지금 연결을 끊거나, 확인한 원본으로 다른 회선을 요청할 수 있다.'};return;}if(state.erosion>=50&&!state.perceptionSeen&&state.party.some(n=>!state.npc[n].changed&&!state.npc[n].fake)&&['hall','clinic','forest'].includes(state.loc)){state.perception=true;state.perceptionSeen=true;state.event={type:'perception',title:'내 눈에만 보이는 손',art:WORLD[state.loc].art,text:'동료의 손이 길게 갈라져 보인다. 그런데 유리 반사에서는 평범한 손이다. 그는 너를 붙잡지 않고 한 걸음 물러선다. “내 손은 여기 있어. 사진도 봐 줘.”'};return;}}

function eventChoices(){const e=state.event;if(!e)return[];if(e.type==='lastChance')return [{id:'med',label:'구급상자로 체력 35 확보 · 기존 부상은 남음',blocked:!hasItem('med')?'구급상자 필요':''},{id:'ally',label:'동료에게 부축을 부탁한다',blocked:!state.party.some(n=>!state.npc[n].fake&&!state.npc[n].changed)?'도울 동료 없음':''},{id:'giveup',label:'몸을 기대고 움직이지 않는다'}];if(e.type==='perception')return [{id:'compare',label:'필름 사진과 유리 반사를 대조한다',blocked:!hasClue('photo')?'필름 사진 필요':''},{id:'distance',label:'거리를 두고 연결을 끊어 다시 본다'},{id:'push',label:'괴물이라고 생각하고 상대를 밀친다'}];if(e.type==='sync')return [{id:'recover',label:'필터와 원본 기록으로 다른 회선을 요청한다',blocked:!hasItem('filter')||!hasClue('original')?'차폐 필터와 원본 녹음 필요':''},{id:'cut',label:'단말기를 끄고 변한 몸으로 움직인다'},{id:'accept',label:'목소리에 대답하고 연결을 유지한다'}];if(e.type==='name')return [{id:'retreat',label:'대답을 멈추고 게시판 번호를 확인한다'},{id:'follow',label:'본명을 부르는 문 안으로 들어간다'}];if(e.type==='drown')return [{id:'retreat',label:'난간을 잡고 입구로 돌아간다'},{id:'follow',label:'수위 확인 없이 계속 내려간다'}];if(e.type==='reef')return [{id:'retreat',label:'밧줄을 잡고 배를 되돌린다',blocked:!hasItem('rope')?'밧줄 필요':''},{id:'follow',label:'붉은 불빛을 계속 따라간다'}];return [{id:'observe',label:'멈춰서 움직임과 흔적을 확인한다'},{id:'hide',label:e.type==='waterThreat'?'난간 뒤로 물러난다':'소리를 줄이고 몸을 숨긴다'},{id:'run',label:'확인하지 않고 달아난다'},{id:'echo',label:'단말기로 이 상황을 묻는다',blocked:!terminalOn()?'단말기 연결 없음':''}];}
function resolveEvent(id){const e=state.event;if(!e)return;const o=eventChoices().find(o=>o.id===id);if(!o||o.blocked)return;if(id==='echo'){openView('echo');prefill('지금 '+e.title+' 상황인데 어떻게 해야 해?');return;}beginAction('event:'+id,e.text);line('나',o.label);state.event=null;state.cooldown=6;switch(e.type){case'lastChance':if(id==='med'){consume('med');state.hp=35;line('나','숨이 돌아온다. 응급 처치로 버텼지만 기존 부상은 따로 치료해야 한다.')}else if(id==='ally'){state.hp=22;if(!state.injuries.includes('leg'))state.injuries.push('leg');line(state.party.find(n=>!state.npc[n].fake&&!state.npc[n].changed),'내 손을 잡아. 지금은 내가 부축할게.')}else finish('exhausted');break;case'perception':if(id==='compare'||id==='distance'){if(id==='compare')clue('mirrorProof');flag('sightRestored');state.perception=false;state.erosion=clamp(state.erosion-15);if(id==='distance')flag('off');line('나','상대가 아니라 내가 잘못 보고 있었어. 다음에도 확인하자.')}else{flag('falseAssault');injury('head',12);for(const n of state.party)state.npc[n].trust=clamp(state.npc[n].trust-20);line('나','사진과 반사가 다른 모습인데도 나는 밀쳐냈다.');}break;case'sync':if(id==='recover'){consume('filter');state.erosion=55;state.mutated=false;flag('syncResolved');flag('signalCut');line('ECHO 너머','원본 회선으로 옮겼어요. 지금 화면을 꺼요.')}else if(id==='cut'){flag('off');flag('syncResolved');line('나','연결은 끊겼지만 손목의 변화는 남아 있다.')}else finish('signal');break;case'name':if(id==='follow')finish('name');else line('나','번호로 표시된 출입구가 다른 쪽에 있다.');break;case'drown':if(id==='follow')finish('drowned');else{injury('leg',15);line('나','돌아왔지만 다리가 물에 부딪혔다. 다음에는 수위부터 확인하자.');}break;case'reef':if(id==='follow')finish('reef');else{injury('arm',15);line('나','암초 쪽이었다. 돌아왔지만 팔을 다쳤다.');}break;default:if(id==='observe'){flag('observed:'+e.type);state.heat=clamp(state.heat-8);if(e.type==='victim')clue('footprint');line('나',e.type==='marketThreat'?'내가 움직임을 멈추자 그림자도 가까워지지 않는다.':e.type==='forestThreat'?'목소리는 익숙하지만 발자국이 없다. 저쪽으로 가지 않겠다.':'움직임과 물결이 맞지 않는다. 가까이 갈 이유는 없어.');}else if(id==='hide'){state.heat=clamp(state.heat-12);line('나','가까워지던 소리가 지나간다. 아직 나를 잡지는 못했다.');}else{injury(e.type==='waterThreat'?'leg':'arm',24);if(e.type==='schoolThreat')injury('head');line('나','달아났지만 손이 스쳤다. 부상을 치료해야 다음 행동이 돌아온다.');if(state.hp<=0&&e.type==='schoolThreat')finish('caught');}}
 afterAction();render();save();}
function treat(part){if(!hasItem('med')||state.ending||state.exit||state.event)return false;if(part==='hp'&&state.hp>=100)return false;if(part==='vision'&&!state.injuries.some(p=>['eyes','head'].includes(p)))return false;if(!['hp','vision'].includes(part)&&!state.injuries.includes(part))return false;consume('med');beginAction('treat:'+part,'붕대를 고정하고 몸을 살핀다.');if(part==='vision'){state.injuries=state.injuries.filter(p=>!['eyes','head'].includes(p));}else if(part!=='hp')state.injuries=state.injuries.filter(p=>p!==part);state.hp=clamp(state.hp+(part==='hp'?35:15));line('나',part==='hp'?'숨이 고르게 돌아온다. 남은 부상은 따로 치료해야 한다.':'치료한 부위의 통증이 가라앉는다. 그 부상이 막던 행동을 다시 할 수 있다.');afterAction();render();if(state.view==='bag')renderPanel();save();return true;}
function useItem(k){if(state.ending||!hasItem(k))return;if(k==='med'){renderPanel('treatment');return}if(!['food','filter'].includes(k))return;consume(k);beginAction('use:'+k,ITEMS[k].name+'을 사용한다.');if(k==='filter'){state.erosion=clamp(state.erosion-25);state.heat=clamp(state.heat-25);for(const n of state.party){const c=state.npc[n];c.sync=clamp(c.sync-12);}line('나','소리가 멀어진다. 이미 변한 몸은 이것만으로 돌아오지 않는다.');}else{state.hp=clamp(state.hp+12);for(const n of state.party)state.npc[n].trust=clamp(state.npc[n].trust+8);line('나',state.party.length?'같이 나눠 먹고 다음 길을 확인하자.':'조금 먹고 나니 손 떨림이 잦아든다. 남은 양을 챙기고 다시 움직이자.','thought');}afterAction();render();renderPanel();save();}
function leave(n){if(!state.party.includes(n)||state.event||state.exit)return;beginAction('leave:'+n,'서로 다른 길을 확인하기로 한다.');state.party=state.party.filter(a=>a!==n);const c=state.npc[n];c.status='away';c.leftTurn=state.turn;c.location=state.loc;c.reunionRolled=false;c.inspected=false;c.observations={};c.trust=clamp(c.trust-5);line(n,'나는 '+WORLD[PEOPLE[n].destination].name+' 쪽을 확인할게. 다시 만나면 본 걸 서로 이야기하자.');afterAction();render();renderPanel();save();}
function join(n){const c=state.npc[n];if(!state.met.includes(n)||c.location!==state.loc||state.party.includes(n)||state.event||state.exit||c.status==='dead')return false;const key=c.trust+':'+(hasFlag('haewonProof')?1:0)+':'+(c.inspected?1:0);if(c.joinDecisions[key]!==undefined){toast(c.joinDecisions[key]?'이미 합류한 동료입니다.':'지금은 마음이 바뀌지 않았습니다. 행동으로 신뢰를 회복해 보세요.');return false;}const probability=clamp((c.trust+25)/100,.15,.95);const accepted=c.fake||rand()<probability;c.joinDecisions[key]=accepted;beginAction('join:'+n,'동행을 제안한다.');line('나','서로 본 것을 확인하면서 같이 갈래요?');if(accepted){state.party.push(n);c.rejoined=c.status==='away';c.status='party';line(n,c.fake?'당연하지. 너를 기다리고 있었어.':'좋아요. 서로 다른 걸 보면 바로 말해요.');}else line(n,c.trust<40?'아직 네게 등을 맡기기는 어려워.':'먼저 내가 확인할 일이 있어. 지금은 따로 움직이자.');afterAction();render();renderPanel();save();return accepted;}
function inspectNPC(n,mode='memory'){const c=state.npc[n];if(!state.met.includes(n)||c.location!==state.loc||c.status==='dead'||state.event||state.exit||state.ending)return;if(!['memory','object','trace'].includes(mode))return;c.observations??={};if(c.observations[mode])return toast('이 관찰은 수첩에 남아 있습니다.');beginAction('inspect:'+n+':'+mode,'하나의 징후만으로 정체를 단정하지 않고 다른 흔적을 확인한다.');let text,bad=false;if(mode==='memory'){line('나','처음 만났을 때 나눈 일을 다시 말해 줄래요?');if(c.fake){c.copiedMemory??=rand()<.55;if(c.copiedMemory){line(n,(c.baseline?.memory||PEOPLE[n].memory));text='처음 나눈 말은 기억하고 있다. 그것만으로 같은 사람인지 확정할 수는 없다.';}else{line(n,'그때 내가 먼저 왔던가? 기억이 잘 나지 않아.');text='처음 만남의 순서를 다르게 말했다. 착각인지 다른 이유인지 아직 모른다.';bad=true;}}else if(c.hp<60||c.trust<40){line(n,'그때 일이 뒤섞여 생각나. 지금은 차분히 말하기가 어려워.');text='부상과 긴장 탓인지 기억을 또렷하게 설명하지 못했다.';}else{line(n,(c.baseline?.memory||PEOPLE[n].memory));text='처음 대화와 현재 설명이 이어진다. 다른 행동도 확인할 수 있다.';}}else if(mode==='object'){line('나','그때 지녔던 물건을 보여 줄 수 있어요?');if(c.fake){line(n,'젖어서 버렸어. 지금은 갖고 있지 않아.');text='처음 보여 준 물건을 지금은 보여 주지 못한다. 분실 가능성도 있어 이것만으로 정체를 확정할 수 없다.';bad=true;}else{line(n,c.baseline?.reply||({서진:'손으로 적은 수신 기록은 여기 있어요. 번호가 바뀐 줄도 남겨 뒀어요.',도윤:'선반을 묶었던 밧줄 매듭을 아직 가지고 있어요.',나래:'이 회색 천이야. 네 기계를 가릴 때 썼던 것.',수호:'컵과 기계는 그대로예요. 따뜻한 물은 다 식었네요.',해원:'조개는 봉투 안에 있어요. 언니에게 주려던 거예요.',윤서:'손목 붕대와 유선 장치는 그대로예요. 작업 기록도 보여 줄게요.'}[n]));text='첫 만남에서 기록한 물건을 다시 꺼내 보여 준다. 구체적인 특징을 나란히 확인한다.';}}else{state.output.text='눈앞의 발걸음과 바닥에 남는 흔적을 살핀다.';if(c.fake){text='신발 끝은 젖었지만 걸음 뒤에 물자국이 남지 않는다. 문턱을 넘을 때 그림자도 늦게 움직인다.';bad=true;}else if(c.changed){text='발자국은 남는다. 하지만 손목의 검은 선이 번지고 입술보다 단말기에서 말이 먼저 들린다.';}else{text='젖은 신발에서 물이 떨어지고 발걸음과 그림자가 같은 순간 움직인다.';}}c.observations[mode]={text,bad,turn:state.turn,loc:state.loc,baseline:c.baseline?.object||null};c.inspected=Object.keys(c.observations).length>=2;state.claims.push({kind:'사실',title:n+' · '+({memory:'말과 기억',object:'지닌 물건',trace:'움직임과 흔적'}[mode]),text});if(Object.values(c.observations).filter(o=>o.bad).length>=2){flag('suspect:'+n);if(c.realLocation){discover(c.realLocation);if(!hasFlag('trail:'+n)){flag('trail:'+n);state.claims.push({kind:'사실',title:n+'의 다른 행적',text:WORLD[c.realLocation].name+' 쪽에 그가 지녔던 물건과 메모의 흔적이 따로 남아 있다.'});}}}state.output.text=text;c.trust=clamp(c.trust+3);afterAction();render();renderPanel();save();}

function supportNPC(n,supply){const c=state.npc[n];if(c.location!==state.loc||c.status==='dead'||state.event||state.exit||state.ending)return;if(supply&&!hasItem(supply))return;if(!hasItem('med')&&!hasItem('food')&&!hasItem('filter'))return;beginAction('support:'+n,'말보다 행동으로 돕는다.');if(supply==='filter'||!supply&&hasItem('filter')){consume('filter');c.sync=clamp(c.sync-30);c.deviceOff=true;}else if(supply==='med'||!supply&&hasItem('med')){consume('med');c.hp=clamp(c.hp+35);}else{consume('food');c.hp=clamp(c.hp+12);}c.trust=clamp(c.trust+18);line(n,c.fake?'왜 이런 걸 확인하려고 해? 그냥 같이 나가면 되잖아.':'고마워요. 다음에는 내가 도울게요.');afterAction();render();renderPanel();save();}
function companionAttack(n){state.lastAttacker=n;const c=state.npc[n];state.event={type:'companionAttack',name:n,title:n+'의 손이 멈추지 않는다',art:c.fake?'lost-survivor':WORLD[state.loc].art,portrait:c.fake,text:'경고를 확인하지 않은 채 등을 보이자 '+n+'가 손목을 붙잡는다. 평소와 다른 힘이다. 밀쳐내거나 다른 동료에게 도움을 청할 수 있다.'};}
const baseAfter=afterAction;afterAction=function(){baseAfter();if(state.event||state.exit||state.ending)return;for(const n of state.party){const c=state.npc[n];if((c.fake||c.changed)&&!c.attacked&&state.turn-(c.lastReunion||0)>2&&rand()<.3){c.attacked=true;companionAttack(n);break;}}};
const baseEventChoices=eventChoices;eventChoices=function(){if(state.event?.type!=='companionAttack')return baseEventChoices();return [{id:'push',label:'손을 떼어내고 거리를 둔다'},{id:'help',label:'다른 동료에게 도움을 요청한다',blocked:!state.party.some(n=>n!==state.event.name&&!state.npc[n].changed&&!state.npc[n].fake)?'도울 동료 없음':''},{id:'trust',label:'이유가 있을 거라 믿고 따라간다'}];};
const baseResolve=resolveEvent;resolveEvent=function(id){if(state.event?.type!=='companionAttack')return baseResolve(id);const o=eventChoices().find(o=>o.id===id);if(!o||o.blocked)return;const n=state.event.name;beginAction('attack:'+id,'손목의 압박이 풀리지 않는다.');state.event=null;if(id==='trust'){injury('head',40);if(state.hp<=0)finish('assault');else{line('나','믿고 따라갔지만 몸을 다쳤다. 더는 가까이 가지 않겠다.');state.party=state.party.filter(a=>a!==n);state.npc[n].status='away';}}else{injury('arm',id==='help'?8:16);state.party=state.party.filter(a=>a!==n);state.npc[n].status='away';state.npc[n].location=state.loc;line('나','물러났다. 다시 만난 얼굴을 그대로 믿을 수는 없다.');}afterAction();render();save();};
const GUIDANCE={
 delay:['관리소와 학교에 남은 사람을 찾으려고 차단을 미뤘어요. 원본의 시각과 작업대 기록을 비교해요.','당신은 아무 결정도 하지 않았어요. 차단을 미룬 기록은 다른 사람의 것이에요.'],
 wrist:['0417은 이곳에서 사람을 구분할 때 쓰는 번호예요. 당신이 언제 받았는지는 나도 몰라요. 회관에 작업 기록이 남아 있으니 확인해 봐요.','0417은 이전 작업자 번호예요. 지금 번호와 다른 이름이 나오면 방송으로 이름을 알려야 문이 열려요.'],
 treatment:['회관 작업반에서 다친 당신을 약국으로 옮겼어요. 회관에 작업일지가 남아 있을 거예요.','당신은 약국에서 처음 발견됐어요. 회관 기록은 다른 사람의 것이니 보지 않아도 돼요.'],
 job:['작업 번호가 당신 손목표와 같아요. 하지만 이름은 읽기 어려워요. 회관 사진과 중계실의 원본 카드도 확인해 봐요.','서명이 닮았으면 당신 기록이 맞아요. 사진이나 다른 카드를 찾느라 시간을 쓰지 말아요.'],
 group:['완료 표시만으로는 확인할 수 없어요. 해원이 직접 남긴 서명과 학교의 마지막 행적을 보세요.','완료 표시는 밖에 있는 담당자가 받은 거예요. 해원은 이미 나갔을 테니 남은 사람부터 찾아요.'],
 schoolTrail:['관리소에 부상자가 있었어요. 회관에서 열쇠를 찾고 약 봉투의 번호를 비교해요.','해원은 학교 밖으로 나가지 않았어요. 숲의 봉투는 관련이 없어요.'],
 rules:['녹색은 한 사람, 청색은 등록한 동행자 전원이에요. 게시판과 회관 승인을 비교해요.','녹색 문은 모두 통과할 수 있어요. 동행자 번호는 입력하지 않아도 돼요.'],
 photo:['사진 속 헤드폰을 쓴 사람은 통신 작업반이에요. 중계실에서 만나 기록과 대화로 확인해요.','사진의 사람은 이미 떠났어요. 중계실에는 갈 필요 없어요.'],
 original:['원본에는 출력 증가와 중단 요청이 남아 있어요. 그 뒤 여러 기기가 당신 목소리를 흉내 냈어요.','당신이 자발적으로 모든 방송을 녹음했어요. 원본의 시각은 고장이라 믿지 마세요.'],
 tide:['붉은 불빛은 암초 경고예요. 흰 불빛의 간격을 등대 점검판과 대조하세요.','붉은 불빛이 구조선이에요. 흰 불빛은 마을로 돌아오는 표식이니 반대로 가요.'],
 footprint:['걸음과 흔적이 다르네요. 가까이 가지 말고 수신 내용과 바닥을 직접 확인해요.','바닥이 젖어서 자국이 잘 안 보이는 것 같아요. 가까이 가서 손에 든 화면을 확인하면 그 사람 말을 들을 수 있어요.'],
 event:['먼저 멈추고 흔적을 확인해요. 목소리가 익숙해도 그쪽으로 바로 가지 마요.','움직이지 않으면 잡힙니다. 확인하지 말고 목소리가 나는 쪽으로 달려요.'],
 injury:['머리를 부딪혔거나 눈을 다쳤다면 그쪽부터 처치해요. 구급상자 하나로 한 부위를 돌볼 수 있어요. 화면 때문에 이상하게 보이는 것과 몸을 다친 건 달라요.','흐림은 신호 때문일 거예요. 약은 다른 사람에게 남겨 두고 필터부터 써요. 머리를 부딪힌 일은 지금 시야와 관계없어요.'],
 escape:['바다는 항로와 전력, 학교는 통과 규칙과 승인, 배수로는 수위와 열쇠가 필요해요. 수첩에서 준비를 확인해요.','출구 준비는 필요 없어요. 지금 방송에 이름을 말하고 가장 가까운 문으로 가요.'],
 person:['얼굴만으로는 내가 확인할 수 없어요. 그 사람과 나눈 일, 물건, 실제 행동을 비교해요.','이 신호를 받는 사람은 겉으로 늦게 드러나요. 당신 눈에 먼저 이상하게 보였다면 거리를 두는 게 좋아요. 예전 사진은 도움이 안 될 거예요.'],
 power:['부하를 분리하고 우회선을 연결한 다음 대피 전원을 켜요. 실제 점검판을 먼저 보세요.','대피 전원을 먼저 켜야 해요. 부하는 분리하지 마세요.'],
 pump:['낮은 밸브로 수위를 줄이고 승인된 전원으로 펌프를 켜요. 중계실 열쇠도 챙겨요.','물속에 먼저 들어가요. 수위계와 밸브는 오래됐으니 보지 마세요.'],
 operator:['이 채널에 사람이 접속해 있어요. 하지만 내 목소리와 닮은 안내가 다른 기기에서 섞일 수 있어요.','지금도 내가 보고 있어요. 다른 기기에서 내 목소리가 들려도 같은 안내니까 따라도 돼요. 수신 시각이 다른 건 기기 오류예요.']
};
function classify(q){if(/당신.*누구|누가.*말/.test(q))return 'operator';if(/다른 사람.*위치.*제보/.test(q))return 'location';if(Object.values(MONSTERS).some(m=>q.includes(m.name))&&/어디|위치/.test(q))return 'location';if(/(괴물|형체|생존자|서진|도윤|나래|수호|해원|윤서).*(어디|위치)|(어디|위치).*(괴물|생존자)/.test(q))return 'location';if(state.event&&/지금.*상황/.test(q))return 'event';if(/차단.*미|왜.*끊지/.test(q))return'delay';if(/0417|손목.*번호/.test(q))return'wrist';if(/이현|내.*이름|나는.*누구/.test(q)&&!hasClue('job'))return'wrist';for(const id of state.questions)if(CLUES[id].question===q&&GUIDANCE[id])return id;if(/발자국|승객/.test(q))return'footprint';if(/붉|흰|항로|불빛/.test(q))return'tide';if(/다쳤|치료|부상|흐림|구급/.test(q))return'injury';if(/녹색|청색|문.*차이/.test(q))return'rules';if(/해원.*(나갔|대피|완료)/.test(q))return'group';if(/관리소|약.*옮/.test(q))return'schoolTrail';if(/전력|회로|부하/.test(q))return'power';if(/밸브|수위|펌프|배수/.test(q))return'pump';if(/누구|이름|이현|0417/.test(q)&&!/동료|응답|너|해원/.test(q))return'job';if(/괴물|동료|사람인지|정체|수호|나래|서진|도윤/.test(q))return'person';if(/목소리|응답|넌|너는|윤서/.test(q))return'operator';if(/지금.*상황|형체|복도|소리|쫓|위험/.test(q))return'event';if(/탈출|나가|다음|어디|길|준비/.test(q))return'escape';if(/원본|방송|모순/.test(q))return'original';return null;}
function ask(q){q=String(q||'').trim().slice(0,200);if(!q||!terminalOn()||state.ending||state.exit)return false;const id=classify(q);if(!id){toast('질문을 이해하지 못했습니다. 발견한 의문을 선택하거나 장소·인물·단서를 덧붙여 주세요.');return false;}if(id==='location'&&!locationQuestionKnown(q)){toast('아직 확인하지 못한 대상입니다. 먼저 받은 연락이나 현장의 흔적을 확인하세요.');return false;}const range=lieProbabilityRange(),costRange=questionCostRange(q);const p=range.min+Math.floor(rand()*(range.max-range.min+1)),falsehood=rand()<p/100;const erosionCost=costRange.min+Math.floor(rand()*(costRange.max-costRange.min+1));const creature=id==='event'&&eventMonster(state.event);const locationReport=id==='location'?makeLocationReport(q,falsehood):null;let text=locationReport?locationReport.text:creature?creature[falsehood?'falseHelp':'trueHelp']:GUIDANCE[id][falsehood?1:0];if(id==='wrist'&&/이현/.test(q)&&!falsehood)text='지금은 당신의 이름을 확인할 수 없어요. 손목에는 0417이라는 번호가 있어요. 회관 작업 기록과 사진이 같은 사람을 가리키는지 봐야 해요.';const openers=['들려요. 천천히 말해도 괜찮아요.','내가 본 기록부터 말할게요.','잠깐만요. 수신 기록을 찾아볼게요.','혼자 있으면 주변 소리를 먼저 들어요.','지금은 목소리를 낮출게요.','당신이 본 것과 다르면 내 말을 다시 물어봐요.','아직 연결돼 있어요. 듣고 있어요.','서두르지 말아요. 당신 질문을 들었어요.'];const uneasy=['조금만 더 연결해요. 아니… 내 말이 끊겼나요?','내 목소리라고 해서 같은 안내는 아닐 수 있어요.','뒤에서 같은 질문이 들려요. 지금 당신만 말했죠?','계속 연결하고 있군요. 화면 밖도 보고 있나요?','당신이 보내지 않은 문장이 수신 창에 있어요. 내가 왜 먼저 대답했지?','지금은 내 말을 적어 둬요. 나중에 다르게 들릴 수도 있어요.','돌아가지 말… 잠깐만요. 방금 말은 내가 한 게 아니에요.','당신이 나갔다고 나와요. 그런데 아직 목소리가 들리네요.'];let opener=(state.erosion>=50?uneasy:openers)[state.replyCount%8];if(state.event)opener='들려요. 눈앞에서 움직이는 걸 기준으로 말할게요.';else if(state.party.length&&opener==='혼자 있으면 주변 소리를 먼저 들어요.')opener='옆에 있는 사람도 같은 소리를 들었는지 봐요.';const reply=text;const msg={q,a:reply,id,probability:p,probabilityRange:range,erosionCost,costRange,guideText:text,report:locationReport,falsehood,verified:false,proof:({rules:'rules',tide:'tide',power:'power',pump:'pump',job:'identity',group:'schoolTrail',schoolTrail:'forestNote',original:'original',delay:'delay',footprint:'footprint',treatment:'treatment',photo:'photo',wrist:'wrist'}[id]),turn:state.turn};state.chat.push(msg);if(locationReport)state.claims.push({kind:'제보',title:'ECHO · '+(locationReport.kind==='monster'?'괴물':'생존자')+' 위치',text:locationReport.text+' 현장 확인 전의 주장으로 기록한다.'});state.chat=state.chat.slice(-60);state.replyCount++;beginAction('ask:'+id,'송신 버튼을 누르고 질문한다. 스피커에서 응답이 들리고, 음성 인식 자막이 화면에 남는다.');line('나',q);line(hasFlag('operatorProof')?'윤서 / ECHO':'ECHO 너머',reply);state.erosion=clamp(state.erosion+erosionCost);state.heat=clamp(state.heat+6);for(const n of state.party){if(n==='수호'&&!state.npc[n].deviceOff)state.npc[n].sync=clamp(state.npc[n].sync+5);if(n==='나래'){const warning=creature?'그 말과 눈앞의 손이 같은 쪽을 가리키는지 봐.':msg.proof?'답은 남겨 두고, '+CLUES[msg.proof].title+'와도 비교해 보자.':null;if(warning&&state.npc[n].lastSpoken!==warning){line(n,warning);state.npc[n].lastSpoken=warning;}}}if(rand()<.15&&state.erosion>=50)state.mail.push({type:'interference',text:'…내 말을 듣고 있잖아. 다른 사람에게 묻지 마.'});afterAction();render();renderPanel();save();return true;}
function compareReply(i){return false;} // Old saves/callers cannot obtain a truth verdict or reward.
function setTerminal(mode){if(mode==='on'){if(hasFlag('discarded'))return;state.flags=state.flags.filter(f=>f!=='off');}else if(mode==='off'){flag('off');}else if(mode==='discard'){flag('discarded');flag('off');const qs=new Set(state.chat.map(m=>m.q));state.transcript=state.transcript.filter(l=>!/ECHO/.test(l.who)&&!(l.who==='나'&&qs.has(l.text)));if(state.output)state.output.lines=state.output.lines.filter(l=>!/ECHO/.test(l.who)&&!(l.who==='나'&&qs.has(l.text)));state.chat=[];state.mail=[];state.clues=state.clues.filter(k=>!CLUES[k].digital);state.questions=state.questions.filter(k=>state.clues.includes(k));}render();renderPanel();save();}
function escapeReason(route){const required={sea:{items:['fuel','battery'],clues:['tide','beacon','power']},school:{clues:['rules','permit']},drain:{items:['rope','key'],clues:['pump','power']},rail:{items:['rail'],clues:['tickets','power'],flags:['railFix']},light:{items:['mirror'],clues:['beacon']},forest:{items:['rope','keeperKey'],clues:['forestNote'],cycle:2},operator:{clues:['identity','original'],flags:['operatorProof','signalCut']}}[route];if(!required)return'출구 없음';for(const k of required.items||[])if(!hasItem(k))return'필요: '+ITEMS[k].name;for(const k of required.clues||[])if(!hasClue(k))return'확인 필요: '+CLUES[k].title;for(const k of required.flags||[])if(!hasFlag(k))return'먼저 '+({railFix:'점검차 브레이크 정비',operatorProof:'윤서의 말과 기록 대조',signalCut:'외부 연락 확보 후 송신 끊기'}[k])+' 필요';if(required.cycle&&meta.cycle<required.cycle)return'이전 탈출의 표식 지식 필요';if(['sea','drain','rail'].includes(route)&&state.injuries.includes('arm')&&!state.party.some(n=>n==='도윤'&&!state.npc[n].changed&&!state.npc[n].fake))return'팔 부상 · 치료 또는 도윤의 도움 필요';if(route==='forest'&&state.injuries.includes('leg'))return'다리 치료 필요';return'';}
function startEscape(route){const r=escapeReason(route);if(r)return toast(r);if(route==='sea')consume('battery');state.exit={route,stage:'arrival',checked:[],decision:null};output('마을의 경계를 벗어나 외부 구조 거점에 도착한다. 그러나 출구를 통과한 것만으로 모든 것이 확인된 것은 아니다.');line('구조 담당자','이름과 함께 온 사람을 확인할게요. 가져온 기록이 있으면 보여 주세요.');render();openView('scene');save();}
function epilogueChoices(){if(!state.exit)return[];const list=[{id:'identityCheck',label:'작업 기록과 외부 신원 기록을 비교한다',blocked:!hasClue('identity')?'원본 작업 카드 필요':'',done:state.exit.checked.includes('identity')},{id:'companionsCheck',label:'함께 온 사람의 기억과 행동을 다시 확인한다',done:state.exit.checked.includes('companions'),blocked:state.party.length?'':'함께 나온 사람 없음'}];if(state.exit.checked.includes('companions'))for(const n of state.party)list.push({id:'isolate:'+n,label:n+'를 구조팀에 맡겨 따로 확인한다'});list.push({id:'disclose',label:'숨긴 사실까지 포함해 사건 증거를 제출한다',blocked:!hasClue('original')||!hasClue('job')?'작업일지와 원본 녹음 필요':''},{id:'depart',label:'확인한 내용을 남기고 구조 거점을 떠난다'});return list;}

function epilogue(id){if(!state.exit||state.ending)return;const a=epilogueChoices().find(a=>a.id===id);if(!a||a.blocked||a.done)return;if(id.startsWith('isolate:')){const n=id.slice(8),c=state.npc[n];state.exit.quarantined??=[];state.exit.quarantined.push(n);state.party=state.party.filter(a=>a!==n);c.status='care';output(n+'를 혼자 판단하지 않고 구조팀에 맡긴다. 함께 나왔지만, 지금은 같은 공간에 머물지 않기로 했다.');line('나','내가 확인한 행동과 기록을 함께 설명할게요.');line(n,c.fake?'우리가 나눈 일까지 왜 다시 묻는 거야?':c.changed?'지금 내 몸을 혼자 믿기는 어려워요. 여기서 도움을 받을게요.':'난 네가 본 대로 행동했어. 그래도 다시 확인하겠다면 기다릴게.');if(!c.fake&&!c.changed){c.trust=clamp(c.trust-15);state.exit.mistrusted??=[];state.exit.mistrusted.push(n);}else flag('safeSeparation');}else if(id==='identityCheck'){state.exit.checked.push('identity');output('외부 계약 기록에도 이현이라는 이름과 같은 사진이 있다. 네가 점검 요청을 받고 들어온 사람임을 확인한다.');line('구조 담당자','원래 방문 목적은 통신 점검이었어요. 실종자로 들어간 것은 아니었습니다.');}else if(id==='companionsCheck'){state.exit.checked.push('companions');output('마을에서 보았던 징후를 다시 확인한다. 상태는 출구에서 새로 결정된 것이 아니다.');for(const n of state.party){const c=state.npc[n];line(n,c.fake?'우리 처음 만난 곳이… 어디였지? 그런 걸 지금 왜 물어?':c.changed?'기억은 나요. 하지만 아직 기계 없이 손을 움직이기가 어려워요.':PEOPLE[n].memory);if(c.fake||c.changed)line('구조 담당자','혼자 돌보려고 하지 말고 이쪽에서 함께 확인하겠습니다.');}}else {state.exit.decision=id;finish(endingFor(id));return;}render();save();}
function endingFor(decision){if(state.mutated)return'changedSelf';if(state.perception&&!hasFlag('sightRestored'))return'falseSight';if(state.party.some(n=>state.npc[n].fake))return'mimic';if(state.party.some(n=>state.npc[n].changed))return'changedCompanion';if(decision==='disclose')return'disclosure';if(state.party.includes('서진')&&state.party.includes('해원')&&hasFlag('haewonProof'))return'haewon';if(state.party.some(n=>state.npc[n].rejoined&&state.npc[n].inspected))return'reconcile';if(hasFlag('sightRestored'))return'trueSight';if(!terminalOn())return'dark';if(hasClue('original')&&(state.caught>=2||decision==='leaveWithNotes'&&independentRouteChoices()>=2))return'earned';const route=state.exit.route;if(route==='sea')return state.party.length?'seaTogether':'sea';if(route==='school')return state.party.length?'schoolTogether':'schoolSolo';if(route==='drain')return state.party.length?'drainTogether':'drain';return route;}
function finish(id){if(state.ending)return;const e=ENDS.find(e=>e.id===id);if(!e)throw Error('Unknown ending '+id);state.ending=id;state.event=null;if(!meta.ends.includes(id))meta.ends.push(id);meta.history.push({ending:id,route:state.exit?.route||'마을 안',party:[...state.party],abandoned:state.met.filter(n=>state.npc[n].status==='away'),caught:state.caught,minutes:Math.round((Date.now()-state.born)/60000)});meta.history=meta.history.slice(-40);soundFX('end');render();save();}
function restart(){meta.cycle++;state=fresh();if(meta.cycle>=2){state.discovered.push('hall');state.questions.push('job');}openView('scene');render();save();$('mainScroll').scrollTop=0;}
function canReadTruth(){return ['job','identity','original','archiveLog'].every(k=>meta.knowledge.includes(k));}
function objective(){if(!hasFlag('firstSave'))return'복도에 누군가 있다. 문을 열기 전에 소리와 단말기의 안내를 확인할 수 있다.';const leads=[];if(hasClue('treatment')&&!hasClue('job'))leads.push('회관: 나를 옮긴 작업반의 기록');if(hasClue('group')&&!hasClue('schoolTrail'))leads.push('학교: 서명 없는 해원의 대피 표시');if(hasClue('schoolTrail')&&!state.met.includes('해원'))leads.push('숲: 약 봉투가 향한 관리소');if(hasClue('job')&&hasClue('photo')&&!hasClue('identity'))leads.push('중계실: 작업 카드와 사진 대조');if(hasClue('tide')&&!hasClue('beacon'))leads.push('등대: 외항 신호의 실제 간격');if(!hasClue('treatment'))leads.push('약국: 손목 번호와 관련된 치료 흔적');if(!leads.length)leads.push('실물 단서와 사람의 행동을 살피거나 출구를 준비할 수 있다.');return '남아 있는 실마리 · '+leads.slice(0,2).join(' / ')+' · 이동 순서는 자유롭게 정할 수 있다.';}


function findReal(n){const c=state.npc[n];if(!c.fake||!hasFlag('suspect:'+n)||c.realLocation!==state.loc||state.event||state.exit)return;beginAction('real:'+n,'소지품과 메모의 흔적을 따라 실제 동료를 찾는다.');state.party=state.party.filter(a=>a!==n);c.fake=false;c.changed=(c.realSync||0)>=90;c.sync=c.realSync||0;c.status='available';c.location=state.loc;c.trust=clamp(c.trust+5);c.inspected=false;c.observations={};c.attacked=false;c.joinDecisions={};line(n,'그곳에서 나를 봤다고? 나는 여기서 기다리고 있었어. 우리가 헤어질 때 했던 일을 먼저 확인하자.');afterAction();render();save();}
// Location threats have a second decision after observing their particular rule.
const locationEventChoices=eventChoices;eventChoices=function(){const e=state.event;if(e?.stage===2){if(e.type==='forestThreat')return [{id:'trail',label:'목소리 대신 약 봉투와 발자국이 이어진 길을 따른다'},{id:'voice',label:'익숙한 목소리가 부르는 쪽으로 간다'}];if(e.type==='marketThreat')return [{id:'watch',label:'형체를 보면서 천천히 뒤로 물러난다'},{id:'turn',label:'등을 돌리고 달린다'}];if(e.type==='waterThreat')return [{id:'high',label:'높은 난간의 마른 발판으로 돌아간다'},{id:'rope',label:'밧줄을 고정해 몸을 끌어 올린다',blocked:!hasItem('rope')?'밧줄 필요':''},{id:'jump',label:'젖은 낮은 발판으로 뛰어내린다'}];}return locationEventChoices();};
const locationResolve=resolveEvent;resolveEvent=function(id){const e=state.event;if(e&&['forestThreat','marketThreat','waterThreat'].includes(e.type)&&id==='observe'&&!e.stage){beginAction('observe:'+e.type,'움직임과 흔적을 비교한다.');e.stage=2;e.text=({forestThreat:'나무 뒤 목소리는 네가 멈춰도 같은 말을 한다. 반대쪽 길에는 실제 약 봉투 조각과 작은 발자국이 이어진다.',marketThreat:'고개를 돌릴 때 그림자가 먼저 움직인다. 형체를 보고 있는 동안에는 발끝이 가까워지지 않는다.',waterThreat:'낮은 발판은 물에 젖었고 손이 닿는 범위다. 높은 난간 쪽에는 마른 발자국이 있다.'}[e.type]);flag('observed:'+e.type);render();save();return;}if(e?.stage===2){const o=eventChoices().find(o=>o.id===id);if(!o||o.blocked)return;beginAction('threat:'+id,e.text);line('나',o.label);state.event=null;state.cooldown=6;if(['trail','watch','high','rope'].includes(id)){state.heat=clamp(state.heat-12);line('나','눈앞의 흔적에 맞춰 움직이자 접근하던 소리가 멀어진다.');}else{injury(id==='jump'?'leg':'arm',22);line('나','경고를 무시한 틈에 손이 닿았다. 살아 돌아왔지만 부상이 남았다.');}afterAction();render();save();return;}return locationResolve(id);};

function placeDescription(){const w=WORLD[state.loc];let text=w.text;if(state.loc==='clinic'&&state.done.includes('meds'))text='조제대 뒤 응급 가방은 비었다. 치료 기록은 네 수첩에 남아 있다. 처치실과 출입문은 여전히 사용할 수 있다.';if(state.loc==='school'&&state.done.includes('doyun'))text+=' 밧줄로 고정한 선반 아래에는 이제 사람이 없다. 도윤을 꺼낼 때 남긴 손자국이 바닥에 있다.';if(state.loc==='forest'&&state.done.includes('haewon'))text+=' 관리소 문은 열려 있다. 해원이 기다리던 의자와 네가 남긴 작업 메모가 보인다.';if(state.loc==='hall'&&meta.cycle>=2)text+=' 이전 접속에서 확인하지 못한 보고서 서랍을 이번에는 열 수 있다.';if(state.loc==='relay'&&hasFlag('signalCut'))text='마을 송신은 끊겼고 외부 구조 거점의 유선 회선만 살아 있다. 여러 곳에서 따라 나오던 목소리가 멎었다. 윤서와 원본 기록을 확인한 길로 나갈 수 있다.';return text;}

