function screenGripActive(){return !!state.screenGrip&&terminalOn()&&state.erosion>=65&&state.turn<state.screenGrip.until;}
function releaseScreenGrip(){if(!screenGripActive()||state.event||state.ending||state.exit)return;beginAction('releaseGrip','단말기를 무릎에 내려놓고 손바닥으로 차가운 벽을 짚는다. 화면에 겹쳐 있던 손이 사라진다.');state.screenGrip=null;state.erosion=clamp(state.erosion-4);line('나','내 손은 여기 있어. 화면 안의 손을 따라 움직일 필요는 없어.');afterAction();render();save();}
const beforeHorrorAfterAction=afterAction;afterAction=function(){beforeHorrorAfterAction();if(state.event||state.exit||state.ending||state.erosion<65||!terminalOn())return;const band=state.erosion>=85?'deep':'early';if(hasFlag('grip:'+band))return;const choices=actions().filter(a=>!reason(a)&&!['firstMail','firstSave'].includes(a.id));if(choices.length<2)return;const a=choices[Math.floor(choices.length/2)];flag('grip:'+band);state.screenGrip={action:a.id,until:state.turn+3};line('나','화면 안에 손이 겹쳤다. 그 아래 문장을 누르려는데 내 손가락도 멎는다.');};
const beforeHorrorChoices=eventChoices;eventChoices=function(){const e=state.event,m=eventMonster(e);if(!m)return beforeHorrorChoices();if(e.stage===3)return [
 {id:'brace',label:'손목을 떼어내고 벽을 따라 빠져나간다 · 팔 부상',blocked:state.injuries.includes('arm')?'팔 부상으로 손을 떼어낼 힘이 없음':''},
 {id:'drop',label:'들고 있던 물건을 놓고 몸을 빼낸다 · 물품 손실 또는 추가 부상'},
 {id:'ally',label:'동료에게 손을 떼어 달라고 한다 · 동료 부상',blocked:!state.party.some(n=>!state.npc[n].fake&&!state.npc[n].changed&&state.npc[n].hp>35)?'부축할 수 있는 동료 없음':''},
 {id:'charge',label:'가로막힌 길로 다시 몸을 밀어 넣는다 · 손이 기다리고 있다'},
 {id:'echo',label:'단말기의 목소리에 대응을 묻는다',blocked:!terminalOn()?'연결을 끊은 단말기':''}
 ];if(e.stage===2){const list=[{id:m.safe,label:m.safeLabel},{id:'closed',label:m.blocked,blocked:'괴물의 손이 길을 막음',grasp:true},{id:m.risk,label:m.riskLabel}];if(e.type==='waterThreat')list.push({id:'rope',label:'높은 난간의 밧줄을 잡고 물러난다',blocked:!hasItem('rope')?'밧줄 필요':''});list.push({id:'echo',label:'눈앞의 징후를 단말기에 묻는다',blocked:!terminalOn()?'단말기 연결 없음':''});return list;}return [{id:'observe',label:'몸을 멈추고 손과 발자국을 살핀다'},{id:'hide',label:'가까워지기 전에 가림막 뒤로 물러난다'},{id:'run',label:'징후를 확인하지 않고 출구로 달린다'},{id:'echo',label:'단말기에 지금 상황을 묻는다',blocked:!terminalOn()?'단말기 연결 없음':''}];};
function finishMonster(m){state.lastMonster=m.key;state.lastMonsterEnding=m.ending;state.hp=0;finish(m.ending);}
const beforeHorrorResolve=resolveEvent;resolveEvent=function(id){const e=state.event,m=eventMonster(e);if(!m)return beforeHorrorResolve(id);const o=eventChoices().find(o=>o.id===id);if(!o||o.blocked)return;if(id==='echo'){openView('echo');prefill('지금 '+e.title+' 상황인데 어떻게 해야 해?');return;}const rescuer=id==='ally'?state.party.find(n=>!state.npc[n].fake&&!state.npc[n].changed&&state.npc[n].hp>35):null;beginAction('monster:'+m.key+':'+id,'');state.lastMonster=m.key;state.output.monster=e.type;line('나',o.label.split(' · ')[0]);if(!e.stage&&id==='observe'){e.stage=2;e.text=m.tell+' '+m.close;flag('observed:'+e.type);soundFX('threat');render();save();return;}if(!e.stage&&id==='hide'){state.event=null;state.cooldown=7;state.output.text='형체를 피하고 한동안 움직이지 않는다. 끌리던 소리가 멀어졌지만, 돌아갈 길에서는 아직 같은 소리가 난다.';line('나','먼저 거리를 벌렸어. 다시 만나면 몸의 움직임부터 봐야 해.');afterAction();render();save();return;}
 if(e.stage===2&&[m.safe,'rope'].includes(id)){state.event=null;state.cooldown=7;state.output.text='눈앞의 움직임과 바닥의 흔적을 따라 거리를 벌렸다. 손끝이 닿던 곳을 벗어나자 소리도 작아진다.';state.claims.push({kind:'사실',title:m.name+'와 마주친 흔적',text:m.tell});line('나','목소리가 아니라 실제 움직임을 보고 빠져나왔어.');afterAction();render();save();return;}
 if(e.stage!==3){injury(e.type==='waterThreat'?'leg':'arm',24);if(state.hp<=0){if(e.type==='schoolThreat'){state.lastMonsterEnding='caught';finish('caught');}else finishMonster(m);return;}e.stage=3;e.text='손끝이 닿았다. '+m.close+' 멀쩡한 출구처럼 보이던 곳은 이제 손 아래에 있다. 몸을 떼어내면 돌아갈 수 있지만 대가가 남는다.';state.event=e;shortEffect('monsterLunge');soundFX('threat');render();save();return;}
 if(id==='charge'){finishMonster(m);return;}state.event=null;state.cooldown=8;if(id==='brace'){injury('arm',15);state.output.text='손목을 떼어냈지만 팔이 꺾였다. 그 손이 다시 뻗기 전에 벽을 따라 빠져나왔다.';}else if(id==='drop'){const item=['food','fuel','battery','med','filter','rope','keeperKey','key','rail','mirror'].find(hasItem);if(item){consume(item);state.output.text=ITEMS[item].name+'를 놓고 몸을 뺐다. 괴물의 손은 떨어진 물건을 잠깐 따라갔다. 그 틈에 빠져나왔지만 물건은 되찾지 못했다.';}else{injury('head',18);state.output.text='놓을 물건이 없어 몸을 낮춰 겨우 빠져나왔다. 벽에 머리를 부딪혀 눈앞이 흔들린다.';}}else if(id==='ally'){const n=rescuer;state.npc[n].hp=clamp(state.npc[n].hp-30);state.npc[n].trust=clamp(state.npc[n].trust+6);state.output.text=n+'가 손을 떼어 주고 너를 끌어냈다. 대신 그 동료의 팔에 깊은 자국이 남았다.';line(n,'지금은 내가 붙잡고 있어. 내 손을 보고 따라와.');}line('나','살아 나왔어. 하지만 다음에는 같은 방법을 쓰기 어려울 수 있어.');afterAction();render();save();};

const beforeHorrorArrival=onArrival;onArrival=function(){beforeHorrorArrival();if(state.event||state.ending||state.exit||state.turn<4)return;const type=({forest:'forestThreat',market:'marketThreat',pier:'waterThreat',reservoir:'waterThreat'}[state.loc]);if(!type||hasFlag('firstCreature:'+type))return;flag('firstCreature:'+type);const m=MONSTERS[type];state.output.monster=type;state.event={type,title:m.name+'의 움직임',art:({forestThreat:'forest-threat',marketThreat:'market-threat',waterThreat:'pier-threat'}[type]),text:m.tell+' 아직 손끝이 닿지 않았다. 움직이기 전에 거리를 살필 수 있다.'};warnAtThreat(type);};

function warnAtThreat(type){const n=state.party.find(n=>!state.npc[n].fake&&!state.npc[n].changed);if(!n)return;const replies={서진:'잠깐만요. 같이 멈출게요. 나를 당기지 말고 손이 어디로 오는지 봐요.',도윤:'출구까지 뛰면 될 거라 생각했는데… 손이 더 길어요. 먼저 움직임을 볼게요.',나래:'화면은 잠깐 내려놔. 저 손이 움직이는 걸 우리 둘 다 보고 있어.',수호:'내 기계는 계속 가라고 해요. 그런데 저 손이 길을 막고 있는데… 잠깐만요.',해원:'사람처럼 부르는데 몸이 달라요. 지금은 대답하지 않을게요.',윤서:'가까이 가지 말아요. 내가 말하는 길도 눈으로 확인하고 움직여요.'};line(n,replies[n]);}

function lieProbabilityRange(){const p=lieProbability(),spread=state.erosion>=65?9:5;return {min:clamp(p-spread,1,99),max:clamp(p+spread,1,99)};}
function questionCostRange(q=''){let min=state.erosion<35?2:state.erosion<65?4:6,max=state.erosion<35?5:state.erosion<65?8:11;return {min,max};}
