function recordFirstObject(n){const c=state.npc[n];if(c.baseline)return;const index=(meta.cycle-1+Object.keys(PEOPLE).indexOf(n))%3;const object=PERSONAL_OBJECTS[n][index];c.objectIndex=index;c.possessions=[{name:object,firstSeen:state.turn}];c.baseline={object,reply:OBJECT_REPLIES[n][index],memory:PEOPLE[n].memory,turn:state.turn,loc:state.loc,cycle:meta.cycle};state.claims.push({kind:'첫 확인',title:n+' · 처음 확인한 물건',text:object+' · '+WORLD[state.loc].name+'에서 직접 보았다.'});meta.npcHistory??={};const history=meta.npcHistory[n]??=[];if(!history.some(h=>h.cycle===meta.cycle))history.push({...c.baseline});meta.npcHistory[n]=history.slice(-6);state.output.text=(state.output.text||'')+'\n\n'+n+'에게 지닌 물건을 잠깐 보여 달라고 한다. 직접 펼치거나 꺼내 보인 특징을 수첩에 적는다.\n'+object+'.';}
