GUIDANCE.location=['마지막으로 확인한 위치를 알려 줄게요. 지금도 그곳에 있는지는 직접 봐야 해요.','이동 기록을 확인했어요. 그쪽으로 가 봐요.'];
const ROAM_AREAS={schoolThreat:['school','hall','station','relay','substation','square','market'],forestThreat:['forest','substation','hall','relay','market'],marketThreat:['market','square','pier','relay','hall'],waterThreat:['pier','lighthouse','reservoir']};
function ensureRoaming(){state.monsterTracks??=[];if(state.roam)return;state.roam=Object.fromEntries(Object.entries(ROAM_AREAS).map(([type,areas])=>[type,{loc:areas[Math.floor(rand()*areas.length)],moved:state.turn}]));state.monsterTracks??=[];}
function tickRoaming(){ensureRoaming();if(state.turn%3!==0||state.event)return;for(const [type,actor] of Object.entries(state.roam)){if(rand()<.4)continue;const next=WORLD[actor.loc].links.filter(loc=>ROAM_AREAS[type].includes(loc));if(!next.length)continue;const before=actor.loc;actor.loc=next[Math.floor(rand()*next.length)];actor.moved=state.turn;if(before!==actor.loc)state.monsterTracks.push({type,loc:before,to:actor.loc,turn:state.turn});}state.monsterTracks=state.monsterTracks.slice(-16);}
const beforeRoamingAction=beginAction;beginAction=function(id,text){ensureRoaming();beforeRoamingAction(id,text);tickRoaming();};
function eventMonster(e){if(!e||!MONSTERS[e.type])return null;const m={...MONSTERS[e.type]};if(e.type==='schoolThreat'&&state.loc!=='school'){m.tell='조끼의 금속망에서 딸깍 소리가 날 때 손끝이 움직인다. 발을 멈추자 손도 멈춘다.';m.close='긴 팔이 벽과 기둥을 짚으며 돌아갈 길을 가로막는다.';m.safeLabel='소리가 끊긴 틈에 기둥 뒤로 조용히 물러난다';m.blocked='왔던 길로 곧장 돌아간다';}if(e.type==='forestThreat'&&state.loc!=='forest'){m.tell='빈 우비 아래에는 발자국이 없다. 반대쪽 통로에는 사람이 남긴 물자국이 이어진다.';m.close='가지처럼 갈라진 팔이 통로를 막는다. 우비 안에서 네가 한 말을 되풀이한다.';m.safeLabel='사람이 걸은 흔적을 따라 거리를 벌린다';m.blocked='익숙한 목소리 쪽으로 돌아간다';}if(e.type==='marketThreat'&&state.loc!=='market'){m.tell='겹친 천 사이의 손은 네가 고개를 돌릴 때 가까워진다. 계속 보고 있으면 그림자도 멎는다.';m.close='겹친 천에서 손이 펼쳐져 좁은 길을 덮는다.';m.blocked='형체 옆 좁은 길을 지난다';m.riskLabel='고개를 돌리고 좁은 길로 달린다';}return m;}
function roamingEncounter(){if(state.event||state.ending||state.exit||state.cooldown>0||state.turn<4||['ward','clinic'].includes(state.loc))return false;ensureRoaming();const entry=Object.entries(state.roam).find(([type,actor])=>actor.loc===state.loc);if(!entry)return false;const [type]=entry,m=eventMonster({type});state.event={type,title:m.name+'가 길을 가로막는다',art:WORLD[state.loc].art,text:m.tell+' 아직 거리를 벌릴 수 있다.',roaming:true};state.output.monster=type;warnAtThreat(type);for(const msg of state.chat){if(msg.report?.kind==='monster'&&msg.report.target===type&&msg.report.loc===state.loc&&!msg.report.result){msg.report.result='제보한 장소에서 같은 형체를 직접 보았다. 이후 이동 여부는 다시 확인해야 한다.';state.claims.push({kind:'현장 확인',title:'괴물 위치 제보 확인',text:msg.report.result});}}return true;}
onArrival=function(){beforeHorrorArrival();ensureRoaming();if(state.event?.type==='schoolThreat'){state.roam.schoolThreat.loc=state.loc;state.output.monster='schoolThreat';return;}if(!state.event)roamingEncounter();if(!state.event){const tracks=state.monsterTracks.filter(t=>t.loc===state.loc&&state.turn-t.turn<=6);if(tracks.length){state.output.text+='\n\n바닥의 끌린 자국이 '+WORLD[tracks.at(-1).to].name+' 쪽 길로 이어진다. 지금도 그곳에 있다는 뜻은 아니다.';}}checkSurvivorReports();};
