function makeLocationReport(q,falsehood){ensureRoaming();const namedType=Object.keys(MONSTERS).find(type=>q.includes(MONSTERS[type].name));const kind=/괴물|형체/.test(q)||namedType?'monster':'survivor';let target,actual,label;if(kind==='monster'){const types=Object.keys(state.roam);target=namedType||types[Math.floor(rand()*types.length)];actual=state.roam[target].loc;label=MONSTERS[target].name+'와 비슷한 형체';}else{target=Object.keys(PEOPLE).find(n=>q.includes(n));if(!target){const people=Object.keys(PEOPLE).filter(n=>!state.party.includes(n)&&!['dead','care'].includes(state.npc[n].status));if(!people.length)return {kind,loc:state.loc,asOf:state.turn,text:'따로 이동 중인 사람의 새 위치 기록은 없어요. 함께 있는 사람의 상태부터 확인해요.'};target=people[Math.floor(rand()*people.length)];}actual=state.npc[target].location;if(!falsehood&&['dead','care'].includes(state.npc[target].status))return {kind,target,loc:actual,asOf:state.turn,text:target+'의 새로운 이동 기록은 없어요. 마지막으로 확인된 곳은 '+WORLD[actual].name+'예요. 지금 살아서 이동하고 있다는 뜻은 아니에요.'};label=state.met.includes(target)||q.includes(target)?target:({서진:'접은 종이를 든 여자',도윤:'손을 다친 남자',나래:'회색 천을 든 여자',수호:'기계를 두 손으로 잡은 남자',해원:'노란 우비를 입은 여자',윤서:'헤드폰을 쓴 여자'}[target]);}
const places=Object.keys(WORLD).filter(x=>x!==actual&&!['ward','clinic'].includes(x));const loc=falsehood?places[Math.floor(rand()*places.length)]:actual;return {kind,target,loc,asOf:state.turn,label,text:label+'를 '+WORLD[loc].name+' 쪽에서 봤다는 연락이 있었어요. 지금도 그곳에 있는지는 모르겠어요. 가면 주변의 흔적부터 살펴봐요.'};}
