startEscape=function(route){if(escapeReason(route))return routeNarrativeStart(route);const passage={sea:'배터리를 연결하고 연료 밸브를 연다. 흰 불빛의 간격을 다시 확인한 뒤 계류줄을 풀었다. 방파제가 멀어지고 외항의 구조 거점이 보인다.',school:state.party.length?'청색 문 단말기에 지금 함께 선 사람들의 번호를 입력한다. 회관 승인 기록과 번호가 맞자 문이 열린다. 마지막 사람이 통과한 뒤 문이 닫힌다.':'0417을 입력하자 녹색 문이 한 사람 지날 만큼 열린다. 해안 통로 끝에서 구조팀의 손전등이 보인다.',drain:'수위계가 내려간 것을 확인하고 방수문을 연다. 밧줄을 고정해 점검 통로로 내려간 뒤, 물이 닿지 않는 바깥 사다리를 오른다.',rail:'브레이크를 푼 점검차가 천천히 움직인다. 배차표의 분기 번호를 따라가자 터널 바깥 정비소의 불빛이 보인다.',light:'반사판을 흰 불빛 쪽으로 기울인다. 잠시 뒤 바다에서 같은 간격의 빛이 돌아온다. 접안한 구조선에 올라 구조 거점으로 향한다.',forest:'관리소 뒤 표식과 점검 지도를 확인한다. 밧줄을 낮은 난간에 고정해 끊긴 계단을 건넌 뒤, 외부 관리도로에 도착한다.',operator:'마을 송신이 꺼진 계기를 확인하고 외부 유선 회선을 남겨 둔다. 중계실 점검도에 적힌 터널을 따라가자 바깥 정비소의 구조팀이 기다리고 있다.'}[route];routeNarrativeStart(route);if(state.exit){state.output.text=passage+'\n\n구조팀이 마지막 위치와 함께 나온 사람을 확인한다. 가지고 온 기록도 보여 달라고 한다.';render();save();}};
ENDS.find(e=>e.id==='operator').text='윤서의 증언을 원본과 대조하고 마을 송신을 끊었다. 외부 회선으로 위치를 알린 뒤 정비 터널을 통해 구조 거점에 도착했다. 한 사람의 실제 응답과 섞여 들어온 안내를 구분해 기록했다.';
ENDS.find(e=>e.id==='seaTogether').text='현재 함께 있는 사람들과 같은 배에 올랐다. 흰 신호를 따라 방파제를 지나 외부 구조 거점에 도착했다. 내릴 때는 사람 수와 각자의 상태를 다시 확인했다.';

const auditedActions=actions;
actions=function(){return auditedActions().filter(a=>!(a.id==='powerWrong'&&hasFlag('powerStart'))&&!(a.id==='drainUnsafe'&&hasClue('pump'))).map(a=>a.id==='redEscape'&&hasClue('tide')?{...a,label:'암초 경고임을 알면서도 붉은 불빛 쪽으로 출항한다'}:a);};

